local({
  language <- sapply(tbl[paste0("hrf12_", 1:20)], as.numeric)
  child <- language[cbind(seq_len(nrow(language)), as.numeric(studychild))]
  recode_values(
    child,
    1 ~ "Country language only",
    2 ~ "Another language, country language not recorded",
    default = "Unknown"
  )
})

local({
  mother <- case_when(
    as.numeric(PCChildRel) %in% 1:4 & as.numeric(PCSex) == 2 ~ as.numeric(hrf14),
    as.numeric(SCChildRel) %in% 1:4 & as.numeric(SCSex) == 2 ~ as.numeric(hrf15),
    .default = NA_real_
  )
  age <- sapply(tbl[paste0("hrf4_", 1:20)], as.numeric)[cbind(seq_along(mother), mother)]
  if_else(age %in% 0:110, age + 0.5, NA_real_)
})
